using System;using EmberBastion;
class EnemyWeaknessChecks{
 static void Near(double actual,double expected,string label){if(Math.Abs(actual-expected)>1e-7)throw new Exception(label+" actual="+actual+" expected="+expected);}
 static double Shot(int mode,int shotKind,int enemyKind){var b=new Battle();b.SetDifficulty(mode);b.Place(0,0);b.Start();b.Units.Clear();var e=new Enemy{Id=900,Kind=enemyKind,HP=1000,MaxHP=1000,Speed=0,Travel=128,Position=Balance.Path(128)};b.Enemies.Add(e);b.Shots.Add(new Shot{Kind=shotKind,Target=900,Position=e.Position,Destination=e.Position,Damage=40,Pen=0,Speed=600,Radius=55});b.Step(1.0/60);return 1000-e.HP;}
 static double Sword(int mode,int enemyKind){var b=new Battle();b.SetDifficulty(mode);b.Place(0,0);b.Start();var e=new Enemy{Id=900,Kind=enemyKind,HP=1000,MaxHP=1000,Speed=0,Travel=128,Position=Balance.Path(128)};b.Enemies.Add(e);b.Step(1.0/60);return 1000-e.HP;}
 static void Main(){try{foreach(int mode in new[]{0,2}){Near(Shot(mode,2,2),24,"baseline bomb shield");Near(Shot(mode,1,1),40,"baseline archer runner");Near(Sword(mode,1),20,"baseline sword runner");}Near(Shot(1,2,2),4,"challenge bomb shield");Near(Shot(1,2,0),40,"challenge bomb other");Near(Shot(1,1,1),60,"challenge archer runner");Near(Shot(1,1,2),44,"challenge archer shield");Near(Shot(1,1,0),40,"challenge archer other");Near(Shot(1,3,1),40,"challenge frost unaffected");Near(Sword(1,1),10,"challenge sword runner");Near(Sword(1,0),20,"challenge sword other");var original=new Battle(13,1);original.SetDifficulty(1);original.Place(0,0);original.Place(1,1);original.Start();for(int i=0;i<800;i++)original.Step(1.0/60);var restored=Battle.ImportCombat(original.ExportCombat());for(int i=0;i<1200;i++){original.Step(1.0/60);restored.Step(1.0/60);if(original.Gold!=restored.Gold||original.Kills!=restored.Kills||original.Enemies.Count!=restored.Enemies.Count||original.Phase!=restored.Phase)throw new Exception("challenge save replay mismatch");for(int j=0;j<original.Enemies.Count;j++)Near(original.Enemies[j].HP,restored.Enemies[j].HP,"challenge restored enemy hp");}Console.WriteLine("PASS challenge-specific weaknesses, baseline and save replay");}catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);}}
}
